  'badges.agir.name': 'Agir',
  'badges.agir.meaning': 'Feuer',
  'badges.agir.how': 'Deine längste Serie, in Tagen.',
  'badges.hefte.name': 'Hefte',
  'badges.hefte.meaning': 'Woche',
  'badges.hefte.how': 'Wochen, in denen du dein Wochenziel erreichst.',
  'badges.roj.name': 'Roj',
  'badges.roj.meaning': 'Tage',
  'badges.roj.how': 'Tage, an denen du lernst — egal welche, egal in welcher Reihenfolge.',
  'badges.vegera.name': 'Vegera',
  'badges.vegera.meaning': 'Rückkehr',
  'badges.vegera.how': 'Zurückkommen nach zwei Wochen oder mehr. Schön, dass du da bist.',
  'badges.pela.name': 'Pêla',
  'badges.pela.meaning': 'Welle',
