  'badges.dilpak.name': 'Dilpak',
  'badges.dilpak.meaning': 'Reinen Herzens',
  'badges.dilpak.how': 'Gewertete Spiele, die du bis zum Ende spielst.',
  'badges.mamik.name': 'Mamik',
  'badges.mamik.meaning': 'Rätsel',
  'badges.mamik.how': 'Tage, an denen du das tägliche Peyvok gelöst hast.',
  'badges.bilbil.name': 'Bilbil',
  'badges.bilbil.meaning': 'Nachtigall',
  'badges.bilbil.how': 'Reime, die du im Reim-Training gefunden hast.',
  'badges.elmas.name': 'Elmas',
  'badges.elmas.meaning': 'Diamant',
  'badges.elmas.how': 'Peyvok-Spiele, die du mit drei Versuchen oder weniger gewonnen hast.',
  'badges.rank-dest.name': 'Deşt',
  'badges.rank-dest.meaning': 'Ebene',
  'badges.rank-dest.how': 'Saisons, in denen du in irgendeinem Spiel Deşt erreichst. Bleibt für immer.',
  'badges.rank-gir.name': 'Gir',
  'badges.rank-gir.meaning': 'Hügel',
  'badges.rank-gir.how': 'Saisons, in denen du in irgendeinem Spiel Gir erreichst. Bleibt für immer.',
  'badges.rank-zozan.name': 'Zozan',
  'badges.rank-zozan.meaning': 'Hochweide',
  'badges.rank-zozan.how': 'Saisons, in denen du in irgendeinem Spiel Zozan erreichst. Bleibt für immer.',
  'badges.rank-ciya.name': 'Çiya',
  'badges.rank-ciya.meaning': 'Berg',
  'badges.rank-ciya.how': 'Saisons, in denen du in irgendeinem Spiel Çiya erreichst. Bleibt für immer.',
  'badges.rank-lutke.name': 'Lûtke',
  'badges.rank-lutke.meaning': 'Gipfel',
  'badges.rank-lutke.how': 'Saisons, in denen du in irgendeinem Spiel Lûtke erreichst. Bleibt für immer.',
  'badges.rank-sterk.name': 'Stêrk',
  'badges.rank-sterk.meaning': 'Stern',
  'badges.rank-sterk.how': 'Saisons, in denen du in irgendeinem Spiel Stêrk erreichst. Bleibt für immer.',
  'badges.hilkiser.name': 'Hilkişer',
  'badges.hilkiser.meaning': 'Kletterer',
  'badges.hilkiser.how': 'Saisons mit zehn gewerteten Spielen in einem Spiel.',
  'badges.cihgirti.name': 'Cihgirtî',
  'badges.cihgirti.meaning': 'Eingestuft',
  'badges.cihgirti.how': 'Beende deine fünf Einstufungsspiele in einem Spiel.',
  'badges.heval.name': 'Heval',
  'badges.heval.meaning': 'Freund:in',
  'badges.heval.how': 'Spiele, die du mit Freunden zu Ende spielst.',
  'badges.diyari.name': 'Diyarî',
  'badges.diyari.meaning': 'Geschenk',
  'badges.diyari.how': 'Tage, an denen du jemandem etwas schenkst — einmal pro Tag und Freund, egal wie viel.',
  'badges.mevandar.name': 'Mêvandar',
  'badges.mevandar.meaning': 'Gastgeber:in',
  'badges.mevandar.how': 'Spiele, die du ausrichtest und die andere mitspielen und beenden.',
